#include "dst_private.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/

void dst_dbg_print_log(void)
{
  #if (DBG_DST == 1)
  
  UInt8 i ;

  dst_log_read(&dst_vars.log[0]) ;
  
  for(i = 0 ; i < DST_LOG_SIZE ; i++)
    {
      UInt8 n ;
 
      dbg_tx_text("\r\nLog #") ; dbg_tx_u   (i + 1 , 1)                 ;

      dbg_tx_text("\r\nPwd: ") ; dbg_tx_h8(dst_vars.log[i].sel_addr)    ;

      dbg_tx_text("\r\nUsr: ") ; dbg_tx_h8(dst_vars.log[i].user_data)   ;

      dbg_tx_text("\r\nMa : ") ; dbg_tx_h8(dst_vars.log[i].ma)          ;

      dbg_tx_text("\r\nUid: ") ;
      for(n = 0 ; n < DST_UID_SIZE_NO_MA ; n++)
        {
          dbg_tx_h8(dst_vars.log[i].uid[n]) ;
        }

      dbg_tx_text("\r\nCh : ") ;
      for(n = 0 ; n < DST_CHALLENGE_SIZE ; n++)
        {
          dbg_tx_h8(dst_vars.log[i].challenge[n]) ;
        }

      dbg_tx_text("\r\nRsp: ") ;
      for(n = 0 ; n < DST_SIGNATURE_SIZE ; n++)
        {
          dbg_tx_h8(dst_vars.log[i].response[n]) ;
        }

      dbg_tx_crlf() ;
    }

  #endif
}
